const program = Effect.gen(function*() {
  yield* Effect.log('Starting...');
  const result = yield* Effect.succeed(42);
  return result;
});

// Effects are NOT promises - you must use a run* function to execute them
async function main() {
  // For async effects:
  const result = await Effect.runPromise(program);
  console.log(result); // 42

  // For sync effects:
  // const result = Effect.runSync(syncEffect);

