main();

import { Effect } from 'effect';

// Create a successful effect
const success = Effect.succeed(42);
// Type: Effect<number, never, never>

// Create a failing effect with a typed error
const failure = Effect.fail(new Error('something went wrong'));
// Type: Effect<never, Error, never>

// Create failure with a custom error class
class ValidationError {
  readonly _tag = 'ValidationError';
  constructor(readonly message: string) {}
}

const validationFailure = Effect.fail(new ValidationError('Invalid email'));
// Type: Effect<never, ValidationError, never>

// Run and handle both cases:
Effect.runPromiseExit(failure).then(exit => {
  if (exit._tag === 'Success') console.log('Success:', exit.value);
  else console.log('Failure:', exit.cause);
});

import { Effect } from 'effect';

const getUserName = (id: number): Effect.Effect<string, Error> =>
  id > 0
    ? Effect.succeed(`User${id}`)
    : Effect.fail(new Error('Invalid ID'));

const program = getUserName(1).pipe(
  Effect.map(name => name.toUpperCase()),         // Transform success value
  Effect.flatMap(name => Effect.succeed(`Hello, ${name}!`)), // Chain effects
  Effect.catchAll(err => Effect.succeed('Guest')), // Handle all errors
  Effect.tap(greeting => Effect.log(greeting)),   // Side effect without changing value
);

Effect.runPromise(program).then(console.log); // Hello, USER1!

import { Context, Effect, Layer } from 'effect';

// Define service interface via Context.Tag
class Database extends Context.Tag('MyApp/Database')<
  Database,
  {
    readonly query: (sql: string) => Effect.Effect<any[], Error>
  }
>() {}

// Implement the service as a Layer
const DatabaseLive = Layer.succeed(Database, {
  query: (sql: string) =>
    Effect.tryPromise({
      try: () => db.execute(sql),
      catch: (err) => new Error(`DB error: ${err}`)
    })
});

// Use the service in effects
const getUsers = Effect.gen(function*() {
  const db = yield* Database;
  return yield* db.query('SELECT * FROM users');
});

// Run with the layer providing the dependency
Effect.runPromise(
  getUsers.pipe(Effect.provide(DatabaseLive))
);

