reference_solution:
import { Effect, Data } from 'effect';

// Use Data.TaggedError for ergonomic tagged errors
class NotFoundError extends Data.TaggedError('NotFoundError')<{
  readonly id: number;
}> {}

class ValidationError extends Data.TaggedError('ValidationError')<{
  readonly field: string;
  readonly message: string;
}> {}

const findUser = (id: number): Effect.Effect<string, NotFoundError | ValidationError> =>
  id <= 0
    ? Effect.fail(new ValidationError({ field: 'id', message: 'Must be positive' }))
    : id === 999
    ? Effect.fail(new NotFoundError({ id }))
    : Effect.succeed(`User${id}`);

const program = findUser(42).pipe(
  Effect.catchTag('NotFoundError', err =>
    Effect.succeed(`No user with id ${err.id}`)
  ),
  Effect.catchTag('ValidationError', err =>
    Effect.fail(new Error(`Invalid: ${err.field} - ${err.message}`))
  )
);

Effect.runPromise(program).then(console.log);

import { Effect, Layer, Context } from 'effect';

class UserRepo extends Context.Tag('UserRepo')<
  UserRepo,
  { getAll: () => Effect.Effect<string[]> }
>() {}

class Logger extends Context.Tag('Logger')<
  Logger,
  { log: (msg: string) => Effect.Effect<void> }
>() {}

// Program that needs both UserRepo and Logger
const program = Effect.gen(function*() {
  const repo = yield* UserRepo;
  const logger = yield* Logger;
  const users = yield* repo.getAll();
  yield* logger.log(`Found ${users.length} users`);
  return users;
});
// Type: Effect<string[], never, UserRepo | Logger>

// Create implementations
const UserRepoLive = Layer.succeed(UserRepo, { getAll: () => Effect.succeed(['Alice', 'Bob']) });
const LoggerLive = Layer.succeed(Logger, { log: (msg) => Effect.sync(() => console.log(msg)) });

// Combine layers and provide to program
const AppLayer = Layer.merge(UserRepoLive, LoggerLive);

// Now R becomes never and Effect.runPromise accepts it
Effect.runPromise(program.pipe(Effect.provide(AppLayer)));

// Schema is now included in the main 'effect' package
import { Schema, Effect } from 'effect';

const UserSchema = Schema.Struct({
  id: Schema.Number,
  name: Schema.String,
  email: Schema.String.pipe(Schema.pattern(/^[^@]+@[^@]+\.[^@]+$/)),
});

type User = Schema.Schema.Type<typeof UserSchema>;

const parseUser = (input: unknown): Effect.Effect<User, Schema.ParseError> =>
  Schema.decodeUnknown(UserSchema)(input);

Effect.runPromise(
  parseUser({ id: 1, name: 'Alice', email: 'alice@example.com' })
).then(console.log);

