import { Effect } from 'effect';
import * as fs from 'fs';

// Effect.sync - for operations that NEVER throw
const getTimestamp = Effect.sync(() => Date.now());

// Effect.try - for operations that MIGHT throw (typed error handling)
const readConfig = Effect.try({
  try: () => {
    const raw = fs.readFileSync('config.json', 'utf8');
    return JSON.parse(raw) as Record<string, string>;
  },
  catch: (err) => new Error(`Failed to read config: ${String(err)}`) // maps thrown value to typed error
});
// Type: Effect<Record<string, string>, Error, never>

// For async functions that might reject:
const fetchData = Effect.tryPromise({
  try: () => fetch('https://api.example.com/data').then(r => r.json()),
  catch: (err) => new Error(`Fetch failed: ${String(err)}`)
});

Effect.runPromise(readConfig).then(console.log).catch(console.error);

