import { Effect } from 'effect';

const fetchUser = (id: number) =>
  Effect.tryPromise({
    try: () => fetch(`/users/${id}`).then(r => r.json()),
    catch: (err) => new Error(`Fetch failed: ${err}`)
  });

// Concurrent execution with Effect.all
const program = Effect.gen(function*() {
  // Default: concurrent
  const [user1, user2] = yield* Effect.all(
    [fetchUser(1), fetchUser(2)],
    { concurrency: 'unbounded' } // run all concurrently
  );

  // Sequential (default in older versions):
  // const [u1, u2] = yield* Effect.all([fetchUser(1), fetchUser(2)]);
  // { concurrency: 1 } or just Effect.all([...])

  return { user1, user2 };
});

Effect.runPromise(program).then(console.log);

