import { Option, Effect } from 'effect';

interface User { id: number; name: string; }
const users: User[] = [{ id: 1, name: 'Alice' }];

// Use Option for values that may be absent
const findUser = (id: number): Option.Option<User> =>
  Option.fromNullable(users.find(u => u.id === id));

// Chain Option operations
const getUsername = (id: number): Option.Option<string> =>
  findUser(id).pipe(
    Option.map(user => user.name),
    Option.map(name => name.toUpperCase())
  );

console.log(Option.getOrElse(getUsername(1), () => 'Unknown')); // ALICE
console.log(Option.getOrElse(getUsername(99), () => 'Unknown')); // Unknown

// Convert Option to Effect when needed in pipelines
const program = Effect.gen(function*() {
  const user = yield* findUser(1).pipe(
    Effect.fromOption(() => new Error('User not found'))
  );
  return user.name;
});

