import { Effect } from 'effect';

declare const db: { connect(): Promise<{ query(sql: string): Promise<any>; release(): Promise<void> }>; };

// Define a scoped resource
const makeConnection = Effect.acquireRelease(
  // Acquire
  Effect.tryPromise({
    try: () => db.connect(),
    catch: (err) => new Error(`Connection failed: ${err}`)
  }),
  // Release (always called, even on error)
  (conn) => Effect.promise(() => conn.release())
);

// Use within a scope
const program = Effect.scoped(
  Effect.gen(function*() {
    const conn = yield* makeConnection;
    const result = yield* Effect.tryPromise({
      try: () => conn.query('SELECT * FROM users'),
      catch: (err) => new Error(`Query failed: ${err}`)
    });
    return result;
  })
);

Effect.runPromise(program).then(console.log);

