import { Effect, Layer, Context } from 'effect';

class Database extends Context.Tag('Database')<Database, { query: () => Effect.Effect<any[]> }>() {}
class Logger extends Context.Tag('Logger')<Logger, { log: (msg: string) => Effect.Effect<void> }>() {}
class Config extends Context.Tag('Config')<Config, { apiKey: string }>() {}

const DatabaseLive = Layer.succeed(Database, { query: () => Effect.succeed([]) });
const LoggerLive = Layer.succeed(Logger, { log: (msg) => Effect.sync(() => console.log(msg)) });
const ConfigLive = Layer.succeed(Config, { apiKey: 'test-key' });

// Compose layers with Layer.merge or Layer.mergeAll
const AppLayer = Layer.mergeAll(DatabaseLive, LoggerLive, ConfigLive);

const program = Effect.gen(function*() {
  const db = yield* Database;
  const logger = yield* Logger;
  const config = yield* Config;
  yield* logger.log(`Using key: ${config.apiKey}`);
  return yield* db.query();
});

Effect.runPromise(program.pipe(Effect.provide(AppLayer)));
